// Genre validation
const validGenres = [
  'Office Equipment & Technology',
  'Food & Drink',
  'Telecommunications & Internet',
  'Healthcare',
  'Education',
  'Tobacco & E-cigarettes',
  'Charity & Nonprofit',
  'Fashion',
  'Retail',
  'Professional & Business Services',
  'Property & Construction',
  'Agencies',
  'Entertainment',
  'Transportation & Logistics',
  'Consumer Electronics',
  'Travel & Tourism',
  'Financial',
  'Utilities & Energy',
  'Leisure & Hospitality',
  'Media & Publishing',
  'Government & Public Sector',
  'Cosmetics & Personal Care',
  'Home & Garden',
  'Automotive',
  'Manufacturing & Industrial',
  'Household Consumer Goods'
];

const results = [];
const errors = [];

for (const item of $input.all()) {
  const url = item.json.URL?.trim();
  const genre = item.json.Genre?.trim();

  if (!url) {
    errors.push({ url: 'empty', genre, reason: 'Missing URL' });
    continue;
  }

  if (!genre) {
    errors.push({ url, genre: 'empty', reason: 'Missing genre' });
    continue;
  }

  if (!validGenres.includes(genre)) {
    errors.push({ url, genre, reason: `Invalid genre: ${genre}` });
    continue;
  }

  // Valid row
  results.push({
    json: {
      url,
      genre,
      client_id: $('Loop Over Clients').item.json.id,
      run_id: $('Create Run Record').first().json.id
    }
  });
}

// Store errors for later logging
$workflow.setStaticData('validation_errors', errors);

return results.slice(0, 200); // Max 200 URLs per run

const cheerio = require('cheerio');

const item = $input.first();
const html = item.json.data;
const originalUrl = item.json.url;
const genre = item.json.genre;
const clientId = item.json.client_id;
const runId = item.json.run_id;

if (!html || typeof html !== 'string') {
  return [{
    json: {
      error: true,
      reason: 'Empty or invalid response',
      url: originalUrl,
      genre,
      client_id: clientId,
      run_id: runId
    }
  }];
}

const $ = cheerio.load(html);

// Extract canonical URL
let canonicalUrl = $('link[rel="canonical"]').attr('href') ||
                   $('meta[property="og:url"]').attr('content') ||
                   originalUrl;

// Normalize canonical URL
if (canonicalUrl && !canonicalUrl.startsWith('http')) {
  try {
    const base = new URL(originalUrl);
    canonicalUrl = new URL(canonicalUrl, base.origin).href;
  } catch (e) {
    canonicalUrl = originalUrl;
  }
}

// Extract publisher/source name
const sourceName = $('meta[property="og:site_name"]').attr('content') ||
                   $('meta[name="application-name"]').attr('content') ||
                   new URL(canonicalUrl).hostname.replace('www.', '');

// Extract title
const title = $('meta[property="og:title"]').attr('content') ||
              $('meta[name="title"]').attr('content') ||
              $('title').text().trim() ||
              $('h1').first().text().trim();

// ============================================
// PUBLISH DATE EXTRACTION (Tiered Approach)
// ============================================
let publishDate = null;
let publishDateSource = null;
let confidence = 0;

// Tier 1: JSON-LD structured data
const jsonLdScripts = $('script[type="application/ld+json"]');
jsonLdScripts.each((i, el) => {
  if (publishDate) return;
  try {
    const data = JSON.parse($(el).html());
    const items = Array.isArray(data) ? data : [data];
    for (const item of items) {
      if (item['@type'] === 'NewsArticle' || item['@type'] === 'Article') {
        if (item.datePublished) {
          publishDate = item.datePublished;
          publishDateSource = 'jsonld';
          confidence = 0.95;
          break;
        }
        if (item.dateModified) {
          publishDate = item.dateModified;
          publishDateSource = 'jsonld_modified';
          confidence = 0.85;
          break;
        }
      }
    }
  } catch (e) {}
});

// Tier 2: OpenGraph / meta tags
if (!publishDate) {
  const ogDate = $('meta[property="article:published_time"]').attr('content');
  if (ogDate) {
    publishDate = ogDate;
    publishDateSource = 'opengraph';
    confidence = 0.90;
  }
}

if (!publishDate) {
  const pubDate = $('meta[name="pubdate"]').attr('content') ||
                  $('meta[name="date"]').attr('content') ||
                  $('meta[name="DC.date"]').attr('content') ||
                  $('meta[name="DC.date.issued"]').attr('content') ||
                  $('meta[itemprop="datePublished"]').attr('content');
  if (pubDate) {
    publishDate = pubDate;
    publishDateSource = 'meta';
    confidence = 0.80;
  }
}

// Tier 3: <time> elements
if (!publishDate) {
  const timeEl = $('time[datetime]').first();
  if (timeEl.length) {
    publishDate = timeEl.attr('datetime');
    publishDateSource = 'time_element';
    confidence = 0.70;
  }
}

// Tier 4: URL date patterns (last resort)
if (!publishDate) {
  const urlDateMatch = canonicalUrl.match(/\/(20[0-9]{2})\/(0[1-9]|1[0-2])\/(0[1-9]|[12][0-9]|3[01])/);
  if (urlDateMatch) {
    publishDate = `${urlDateMatch[1]}-${urlDateMatch[2]}-${urlDateMatch[3]}`;
    publishDateSource = 'url_pattern';
    confidence = 0.50;
  }
}

// ============================================
// CONTENT EXTRACTION (Readability-like)
// ============================================

// Remove unwanted elements
$('script, style, nav, header, footer, aside, .ad, .advertisement, .social-share, .related-articles, .comments').remove();

// Try to find main content
let articleBody = '';
const contentSelectors = [
  'article',
  '[itemprop="articleBody"]',
  '.article-body',
  '.article-content',
  '.post-content',
  '.entry-content',
  '.story-body',
  'main',
  '.content'
];

for (const selector of contentSelectors) {
  const content = $(selector).first();
  if (content.length && content.text().trim().length > 200) {
    articleBody = content.text().trim();
    break;
  }
}

// Fallback to paragraphs if no article container found
if (!articleBody || articleBody.length < 200) {
  const paragraphs = [];
  $('p').each((i, el) => {
    const text = $(el).text().trim();
    if (text.length > 50) {
      paragraphs.push(text);
    }
  });
  articleBody = paragraphs.join('\n\n');
}

// Check for paywall indicators
const paywallIndicators = [
  '.paywall',
  '.subscription-required',
  '[data-paywall]',
  '.premium-content',
  '.subscriber-only'
];

let isPaywalled = false;
for (const selector of paywallIndicators) {
  if ($(selector).length > 0) {
    isPaywalled = true;
    break;
  }
}

// Also check if content is too short (likely blocked)
if (articleBody.length < 300) {
  isPaywalled = true;
}

// Generate dedupe key (SHA256 of canonical URL)
const crypto = require('crypto');
const dedupeKey = crypto.createHash('sha256').update(canonicalUrl).digest('hex').substring(0, 64);

// Normalize title for similarity comparison
const titleNormalized = title ? title.toLowerCase().replace(/[^a-z0-9\s]/g, '').trim() : '';

// Content fingerprint (simple hash of first 1000 chars)
const contentFingerprint = crypto.createHash('sha256').update(articleBody.substring(0, 1000)).digest('hex').substring(0, 64);

return [{
  json: {
    url: originalUrl,
    canonical_url: canonicalUrl,
    genre,
    client_id: clientId,
    run_id: runId,
    source_name: sourceName,
    original_title: title,
    article_body: articleBody,
    publish_date: publishDate,
    publish_date_source: publishDateSource,
    publish_date_confidence: confidence,
    is_paywalled: isPaywalled,
    dedupe_key: dedupeKey,
    title_normalized: titleNormalized,
    content_fingerprint: contentFingerprint,
    word_count: articleBody.split(/\s+/).length
  }
}];

// Validate publish date is within 24h window (07:00 to 07:00 UK)
const item = $input.first().json;

// Check if already errored or paywalled
if (item.error || item.is_paywalled) {
  return [{
    json: {
      ...item,
      skip: true,
      skip_reason: item.error ? item.reason : 'Paywalled or blocked content'
    }
  }];
}

// Must have publish date
if (!item.publish_date) {
  return [{
    json: {
      ...item,
      skip: true,
      skip_reason: 'Could not determine publish date'
    }
  }];
}

// Parse publish date
let pubDate;
try {
  pubDate = new Date(item.publish_date);
  if (isNaN(pubDate.getTime())) {
    throw new Error('Invalid date');
  }
} catch (e) {
  return [{
    json: {
      ...item,
      skip: true,
      skip_reason: `Invalid publish date format: ${item.publish_date}`
    }
  }];
}

// Calculate 24h window (07:00 yesterday UK to 07:00 today UK)
const now = new Date();

// Get current time in UK
const ukFormatter = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/London',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit'
});

// Create window boundaries
// Window end: 07:00 today UK
const todayUK = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/London' }));
todayUK.setHours(7, 0, 0, 0);

// If we're before 07:00 UK, the window end is yesterday at 07:00
const currentHourUK = new Date().toLocaleString('en-US', { timeZone: 'Europe/London', hour: 'numeric', hour12: false });
let windowEnd = todayUK;
if (parseInt(currentHourUK) < 7) {
  // Before 7am, so window ended yesterday at 7am
  windowEnd = new Date(todayUK);
  windowEnd.setDate(windowEnd.getDate() - 1);
}

// Window start: 24 hours before window end
const windowStart = new Date(windowEnd);
windowStart.setDate(windowStart.getDate() - 1);

// Convert publish date to UTC for comparison
const pubDateUTC = pubDate.getTime();
const windowStartUTC = windowStart.getTime();
const windowEndUTC = windowEnd.getTime();

// Check if in window
if (pubDateUTC < windowStartUTC || pubDateUTC > windowEndUTC) {
  return [{
    json: {
      ...item,
      skip: true,
      skip_reason: `Publish date ${item.publish_date} outside 24h window (${windowStart.toISOString()} to ${windowEnd.toISOString()})`
    }
  }];
}

// Valid - pass through with parsed date
return [{
  json: {
    ...item,
    published_at: pubDate.toISOString(),
    skip: false
  }
}];

// Deduplication check
const items = $input.all();
const seen = new Map();
const results = [];
const duplicates = [];

// Sort by confidence (prefer higher confidence publish dates)
items.sort((a, b) => (b.json.publish_date_confidence || 0) - (a.json.publish_date_confidence || 0));

for (const item of items) {
  const key = item.json.dedupe_key;
  const titleNorm = item.json.title_normalized;

  // Check exact URL match
  if (seen.has(key)) {
    duplicates.push({
      ...item.json,
      duplicate_of: seen.get(key),
      duplicate_type: 'url'
    });
    continue;
  }

  // Check title similarity (simple approach - exact normalized match)
  let isDuplicate = false;
  for (const [existingKey, existing] of seen.entries()) {
    if (existing.title_normalized === titleNorm && titleNorm.length > 20) {
      duplicates.push({
        ...item.json,
        duplicate_of: existingKey,
        duplicate_type: 'title'
      });
      isDuplicate = true;
      break;
    }
    // Check content fingerprint
    if (existing.content_fingerprint === item.json.content_fingerprint) {
      duplicates.push({
        ...item.json,
        duplicate_of: existingKey,
        duplicate_type: 'content'
      });
      isDuplicate = true;
      break;
    }
  }

  if (!isDuplicate) {
    seen.set(key, item.json);
    results.push(item);
  }
}

// Store duplicates for logging
$workflow.setStaticData('duplicates', duplicates);

return results;

