// Parse LLM response and merge with original data
const item = $input.first();
const original = item.json;

let llmData;
try {
  llmData = JSON.parse(original.message?.content || original.text || '{}');
} catch (e) {
  // If LLM response parsing fails, use fallbacks
  llmData = {
    polished_title: original.original_title,
    summary: 'Summary unavailable.',
    why_matters: 'Analysis unavailable.',
    agency_relevance_score: 3
  };
}

return [{
  json: {
    ...original,
    polished_title: llmData.polished_title || original.original_title,
    summary: llmData.summary || 'Summary unavailable.',
    why_matters: llmData.why_matters || 'Analysis unavailable.',
    agency_relevance_score: parseInt(llmData.agency_relevance_score) || 3
  }
}];

// Ranking and capping
const items = $input.all();
const maxPerGenre = 6;
const maxTotal = 60;

// Group by genre
const byGenre = {};
for (const item of items) {
  const genre = item.json.genre;
  if (!byGenre[genre]) byGenre[genre] = [];
  byGenre[genre].push(item);
}

// Sort each genre by agency relevance (desc) then recency (desc)
for (const genre in byGenre) {
  byGenre[genre].sort((a, b) => {
    // First by agency relevance score (higher is better)
    const scoreA = a.json.agency_relevance_score || 0;
    const scoreB = b.json.agency_relevance_score || 0;
    if (scoreB !== scoreA) return scoreB - scoreA;

    // Then by recency (newer is better)
    const dateA = new Date(a.json.published_at || 0);
    const dateB = new Date(b.json.published_at || 0);
    return dateB - dateA;
  });
}

// Apply caps and assign ranks
const results = [];
let overallRank = 0;

for (const genre in byGenre) {
  const genreStories = byGenre[genre].slice(0, maxPerGenre);
  genreStories.forEach((item, index) => {
    overallRank++;
    if (overallRank <= maxTotal) {
      results.push({
        json: {
          ...item.json,
          genre_rank: index + 1,
          overall_rank: overallRank
        }
      });
    }
  });
}

// Mark top 5 as top signals
results.sort((a, b) => {
  const scoreA = a.json.agency_relevance_score || 0;
  const scoreB = b.json.agency_relevance_score || 0;
  if (scoreB !== scoreA) return scoreB - scoreA;
  return new Date(b.json.published_at || 0) - new Date(a.json.published_at || 0);
});

results.slice(0, 5).forEach(item => {
  item.json.is_top_signal = true;
});

// Re-sort by genre for output
results.sort((a, b) => {
  if (a.json.genre < b.json.genre) return -1;
  if (a.json.genre > b.json.genre) return 1;
  return a.json.genre_rank - b.json.genre_rank;
});

return results;

// Aggregate all stories for email generation
const allStories = $input.all().map(item => item.json);

// Get client info from earlier in workflow
const client = $('Loop Over Clients').first().json;
const run = $('Create Run Record').first().json;

// Genre colors mapping
const genreColors = {
  'Office Equipment & Technology': '#2563eb',
  'Food & Drink': '#dc2626',
  'Telecommunications & Internet': '#7c3aed',
  'Healthcare': '#059669',
  'Education': '#0891b2',
  'Tobacco & E-cigarettes': '#57534e',
  'Charity & Nonprofit': '#db2777',
  'Fashion': '#c026d3',
  'Retail': '#ea580c',
  'Professional & Business Services': '#4f46e5',
  'Property & Construction': '#ca8a04',
  'Agencies': '#0d9488',
  'Entertainment': '#e11d48',
  'Transportation & Logistics': '#1d4ed8',
  'Consumer Electronics': '#6366f1',
  'Travel & Tourism': '#0284c7',
  'Financial': '#15803d',
  'Utilities & Energy': '#a16207',
  'Leisure & Hospitality': '#be185d',
  'Media & Publishing': '#9333ea',
  'Government & Public Sector': '#1e40af',
  'Cosmetics & Personal Care': '#ec4899',
  'Home & Garden': '#65a30d',
  'Automotive': '#b91c1c',
  'Manufacturing & Industrial': '#475569',
  'Household Consumer Goods': '#d97706'
};

// Get top signals
const topSignals = allStories
  .filter(s => s.is_top_signal)
  .slice(0, 5);

// Group stories by genre
const byGenre = {};
for (const story of allStories) {
  if (!byGenre[story.genre]) byGenre[story.genre] = [];
  byGenre[story.genre].push(story);
}

// Format date for UK
const today = new Date();
const dateStr = today.toLocaleDateString('en-GB', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'Europe/London'
});

// Build email data
return [{
  json: {
    client,
    run,
    dateStr,
    storyCount: allStories.length,
    topSignals,
    storiesByGenre: byGenre,
    genreColors,
    recipients: client.recipients || []
  }
}];

// Generate HTML email
const data = $input.first().json;
const { dateStr, storyCount, topSignals, storiesByGenre, genreColors, client } = data;

// No-news variants
const noNewsVariants = [
  "Today's scan found no stories meeting our quality criteria within the 24-hour window. We'll be back tomorrow with fresh insights.",
  "Our filters didn't surface any qualifying stories today. Sometimes quiet news days happen—we'll return tomorrow with the latest.",
  "No stories passed our quality threshold today. Rest assured, we're monitoring continuously and will deliver tomorrow's brief as usual.",
  "Today's news cycle didn't yield stories meeting our standards. We maintain strict criteria to ensure you only receive relevant, high-quality content.",
  "A rare quiet day in our monitored sources. Our automated checks continue around the clock—expect your next brief tomorrow at 07:00.",
  "No qualifying content today. Our multi-tier validation ensures quality over quantity. Tomorrow's brief will arrive on schedule.",
  "Today's sources didn't produce content meeting our publication criteria. Quality assurance remains our priority—see you tomorrow."
];

// Select variant based on day of year for rotation
const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24));
const variant = noNewsVariants[dayOfYear % noNewsVariants.length];

let html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>44 News Automation - Morning Brief</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
      line-height: 1.6;
      color: #003d96;
      background-color: #f3feff;
      margin: 0;
      padding: 0;
    }
    .container {
      max-width: 680px;
      margin: 0 auto;
      padding: 20px;
    }
    .header {
      text-align: center;
      padding: 30px 20px;
      background: linear-gradient(135deg, #003d96 0%, #0056b3 100%);
      color: white;
      border-radius: 12px 12px 0 0;
    }
    .header h1 {
      margin: 0 0 10px 0;
      font-size: 28px;
      font-weight: 700;
    }
    .header .date {
      font-size: 16px;
      opacity: 0.9;
    }
    .content {
      background: white;
      padding: 30px;
      border-radius: 0 0 12px 12px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    }
    .top-signals {
      background: #f8fafc;
      border-left: 4px solid #003d96;
      padding: 20px;
      margin-bottom: 30px;
      border-radius: 0 8px 8px 0;
    }
    .top-signals h2 {
      margin: 0 0 15px 0;
      font-size: 18px;
      color: #003d96;
    }
    .top-signals ul {
      margin: 0;
      padding-left: 20px;
    }
    .top-signals li {
      margin-bottom: 8px;
    }
    .top-signals a {
      color: #003d96;
      text-decoration: none;
    }
    .top-signals a:hover {
      text-decoration: underline;
    }
    .genre-section {
      margin-bottom: 30px;
    }
    .genre-header {
      color: white;
      padding: 12px 20px;
      border-radius: 8px;
      margin-bottom: 15px;
      font-size: 16px;
      font-weight: 600;
    }
    .story-card {
      background: #f8fafc;
      border-radius: 8px;
      padding: 20px;
      margin-bottom: 15px;
      border-left: 4px solid #e2e8f0;
    }
    .story-card h3 {
      margin: 0 0 10px 0;
      font-size: 17px;
    }
    .story-card h3 a {
      color: #003d96;
      text-decoration: none;
    }
    .story-card h3 a:hover {
      text-decoration: underline;
    }
    .story-card .source {
      font-size: 12px;
      color: #64748b;
      margin-bottom: 10px;
    }
    .story-card .summary {
      font-size: 14px;
      color: #334155;
      margin-bottom: 12px;
    }
    .story-card .why-matters {
      font-size: 13px;
      color: #475569;
      background: #e0f2fe;
      padding: 12px;
      border-radius: 6px;
      border-left: 3px solid #0284c7;
    }
